const siteEdition=new URLSearchParams(location.search).get('edition')==='law'?'law':'one';const siteWorkbench='/account/?edition='+siteEdition;if(new URLSearchParams(location.search).get('page')==='login')location.replace(siteWorkbench);const platformBar=document.createElement('div');platformBar.className='platform-links';platformBar.innerHTML='<strong>Vibe '+(siteEdition==='law'?'Law':'One')+'</strong><a href="/entrance/">Switch entrance</a><a href="'+siteWorkbench+'">My Workbench</a><a href="/practice/?edition='+siteEdition+'">Practice Playground</a><a href="/studio/index.html?edition='+siteEdition+'#/dashboard">Project Studio</a><a href="/plans/?edition='+siteEdition+'">Plans & checkout</a>';document.body.prepend(platformBar);const routePlatform=()=>{if(location.hash.startsWith('#/'))location.href=siteWorkbench+'#build';};routePlatform();addEventListener('hashchange',routePlatform);document.addEventListener('click',event=>{const a=event.target.closest('a');if(!a)return;const href=a.getAttribute('href')||'';if(new URL(a.href,location.href).hash.startsWith('#/')||/page=login/.test(href)){event.preventDefault();event.stopImmediatePropagation();location.href=siteWorkbench;}},true);document.addEventListener('submit',async event=>{if(event.target.id!=='home-brief-form')return;event.preventDefault();event.stopImmediatePropagation();const status=document.querySelector('#home-brief-status');try{await Vibe.require();const edition=siteEdition;if(!Vibe.user.access[edition])throw Error('Activate Vibe '+(edition==='law'?'Law':'One')+' in your account first.');const idea=document.querySelector('#home-idea').value.trim();if(!idea)throw Error('Describe your idea first.');const p=await Vibe.api('/projects',{brief:{name:idea.slice(0,80),goal:idea,edition}});location.href='/practice/?edition='+edition+'&project='+p.id;}catch(e){status.textContent=e.message;}},true);